var doc = Document;
// Goal: turn an enclosed footprint into a named room with a tag and a reported area. This script
// builds the level, plan and walls it needs first (steps 1-2); a real task starts at step 3 with
// walls that exist.
Autodesk.Revit.DB.Level top = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (top == null || l.Elevation > top.Elevation) top = l;
}
double elevation = (top == null ? 0.0 : top.Elevation) + 10.0;
Autodesk.Revit.DB.ViewFamilyType floorPlanType = null;
foreach (Autodesk.Revit.DB.ViewFamilyType vft in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewFamilyType))) {
  if (vft.ViewFamily == Autodesk.Revit.DB.ViewFamily.FloorPlan) { floorPlanType = vft; break; }
}

return Connector.WithTransaction(doc, () => {
  // 1. A level of the script's own, with its floor plan (Level.Create makes no plan view). A room
  //    on a script-created level can report zero area and no boundary until the level's room
  //    computation height is set, so set it now: 4' above the level, inside the wall height.
  var level = Autodesk.Revit.DB.Level.Create(doc, elevation);
  level.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.LEVEL_ROOM_COMPUTATION_HEIGHT).Set(4.0);
  var plan = Autodesk.Revit.DB.ViewPlan.Create(doc, floorPlanType.Id, level.Id);

  // 2. An enclosed 20' x 20' footprint of walls on that level. Walls are room-bounding by default.
  var pts = new[] { new Autodesk.Revit.DB.XYZ(0, 0, elevation), new Autodesk.Revit.DB.XYZ(20, 0, elevation),
                    new Autodesk.Revit.DB.XYZ(20, 20, elevation), new Autodesk.Revit.DB.XYZ(0, 20, elevation) };
  for (int i = 0; i < 4; i++) {
    Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(pts[i], pts[(i + 1) % 4]), level.Id, false);
  }
  doc.Regenerate();

  // 3. Place the room: NewRoom(level, UV) puts a room at that plan point on the level; Revit finds
  //    the enclosing boundary. A point outside any enclosure yields a room with no area.
  var room = doc.Create.NewRoom(level, new Autodesk.Revit.DB.UV(10, 10));
  room.Name = "Meeting";
  doc.Regenerate();

  // 4. Tag it in the level's plan. NewRoomTag's first argument is a LinkElementId (rooms can live
  //    in linked models); for a room in this document wrap its id. The view must be a plan of the
  //    room's level or the call fails inside Revit.
  var tag = doc.Create.NewRoomTag(new Autodesk.Revit.DB.LinkElementId(room.Id), new Autodesk.Revit.DB.UV(10, 10), plan.Id);

  // 5. Verify: a non-zero area, one boundary loop, and the tag points at the room.
  int loops = room.GetBoundarySegments(new Autodesk.Revit.DB.SpatialElementBoundaryOptions()).Count;
  double areaSqFt = room.Area;
  return new {
    roomId = room.Id.Value, roomName = room.Name, areaSqFt, enclosed = loops > 0 && areaSqFt > 0,
    boundaryLoops = loops, tagId = tag.Id.Value, tagPointsAtRoom = tag.Room != null && tag.Room.Id == room.Id,
    levelId = level.Id.Value, planId = plan.Id.Value
  };
});
